#!/usr/bin/env python3
"""Original, individually authored single-serving recipe expansion (group B)."""
import json
from collections import Counter
from pathlib import Path

RECIPES = []
CATEGORY = "main"

def add(slug, name, description, cuisine, difficulty, minutes, ingredients,
        steps, tip, tags, equipment, motif, toppings, garnish="", vessel="plate",
        base="main", colors="#774329 #e9ac25 #24624b #f2d5a0"):
    category = CATEGORY
    rarity = {1: "common", 2: "rare", 3: "special"}[difficulty]
    RECIPES.append({
        "id": "r-" + slug, "name": name, "description": description,
        "category": category, "cuisine": cuisine, "difficulty": difficulty,
        "rarity": rarity, "minutes": minutes, "servings": 1,
        "ingredients": [{"name": part.split("=", 1)[0], "amount": part.split("=", 1)[1]}
                        for part in ingredients.split("|")],
        "steps": steps.split("|"), "tip": tip, "tags": tags.split(" "),
        "equipment": equipment.split(" "), "reward": {1: 20, 2: 40, 3: 70}[difficulty],
        "art": {"vessel": vessel, "base": base, "colors": colors.split(" "),
                "garnish": garnish.split(" ") if garnish else [], "motif": motif,
                "toppings": toppings.split(" ")},
    })

