def main():
    assert len(RECIPES) == 150
    assert Counter(r["category"] for r in RECIPES) == {"main": 75, "side": 75}
    assert len({r["id"] for r in RECIPES}) == len(RECIPES)
    assert len({r["name"] for r in RECIPES}) == len(RECIPES)
    assert all(3 <= len(r["steps"]) <= 6 for r in RECIPES)
    assert all(2 <= len(r["tags"]) <= 5 for r in RECIPES)
    assert all(len(r["ingredients"]) >= 4 for r in RECIPES)
    target = Path(__file__).resolve().parents[2] / "content/expansion/recipes/mains-sides.json"
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text(json.dumps(RECIPES, ensure_ascii=False, indent=2) + "\n")
    print(f"Authored {len(RECIPES)} recipes -> {target}")

if __name__ == "__main__":
    main()
